//! A common junction's incoming road whose `<link>` leaves the junction out.
//!
//! `tests/data/junction_links.xodr` is generated by `junction_links.py`.

use xodr::{
    load_file_with_provenance, load_str_with_provenance, LaneId, Provenance, RoadEnd, Warning,
};

const FIXTURE: &str = "tests/data/junction_links.xodr";

fn lane(prov: &Provenance, road: &str, od_id: i32) -> LaneId {
    prov.lanes
        .iter()
        .find(|p| p.road_id == road && p.od_id == od_id)
        .unwrap_or_else(|| panic!("road {road} lane {od_id}"))
        .lane
}

#[test]
fn a_road_that_leaves_out_its_junction_drives_into_it_from_the_end_its_connecting_road_names() {
    let (net, prov) = load_file_with_provenance(FIXTURE).unwrap();
    let into = net.lane(lane(&prov, "1", -1)).unwrap();
    assert_eq!(into.successors, [lane(&prov, "10", -1)]);
    let out = net.lane(lane(&prov, "10", -1)).unwrap();
    assert_eq!(out.predecessors, [lane(&prov, "1", -1)]);
    assert_eq!(out.successors, [lane(&prov, "2", -1)]);
}

#[test]
fn the_crate_warns_that_the_link_is_missing() {
    let (_, prov) = load_file_with_provenance(FIXTURE).unwrap();
    let missing: Vec<_> = prov
        .warnings
        .iter()
        .filter(|w| matches!(w, Warning::JunctionLinkMissing { .. }))
        .collect();
    assert_eq!(
        missing,
        [&Warning::JunctionLinkMissing {
            road_id: "1".into(),
            junction_id: "5".into(),
            end: RoadEnd::End,
        }]
    );
    assert_eq!(
        missing[0].to_string(),
        "road \"1\": its <link> leaves out junction \"5\" at its end, linked from the junction's connecting road"
    );
    assert_eq!(missing[0].road_id(), "1");
}

#[test]
fn a_road_whose_connecting_road_does_not_name_it_stays_unlinked() {
    let (net, prov) = load_file_with_provenance(FIXTURE).unwrap();
    assert!(net
        .lane(lane(&prov, "3", -1))
        .unwrap()
        .successors
        .is_empty());
    assert!(!prov.warnings.iter().any(|w| w.road_id() == "3"));
}

#[test]
fn a_connecting_road_that_names_no_contact_point_leaves_the_road_unlinked() {
    let xml = std::fs::read_to_string(FIXTURE).unwrap().replace(
        r#"<predecessor elementType="road" elementId="1" contactPoint="end"/>"#,
        r#"<predecessor elementType="road" elementId="1"/>"#,
    );
    let (net, prov) = load_str_with_provenance(&xml).unwrap();
    assert!(net
        .lane(lane(&prov, "1", -1))
        .unwrap()
        .successors
        .is_empty());
    assert!(!prov
        .warnings
        .iter()
        .any(|w| matches!(w, Warning::JunctionLinkMissing { .. })));
}

#[test]
fn a_link_part_way_along_a_road_outside_a_virtual_junction_joins_nothing() {
    let road = |id: &str, y: f64, link: &str| {
        format!(
            r#"<road id="{id}" length="200" junction="-1">{link}<planView>
            <geometry s="0" x="0" y="{y}" hdg="0" length="200"><line/></geometry></planView>
            <lanes><laneSection s="0"><center><lane id="0" type="none"/></center><right>
            <lane id="-1" type="driving"><link><successor id="-1"/></link>
            <width sOffset="0" a="3.5" b="0" c="0" d="0"/></lane>
            </right></laneSection></lanes></road>"#
        )
    };
    let xodr = format!(
        "<OpenDRIVE><header/>{}{}</OpenDRIVE>",
        road("1", 0.0, ""),
        road(
            "10",
            20.0,
            r#"<link><successor elementType="road" elementId="1" elementS="50" elementDir="+"/></link>"#
        )
    );
    let net = xodr::load_str(&xodr).unwrap();
    assert!(net.lanes().iter().all(|l| l.successors.is_empty()));
}

#[test]
fn a_road_link_without_a_contact_point_warns_and_joins_the_start() {
    let road = |id: &str, x: f64, link: &str| {
        format!(
            r#"<road id="{id}" length="50" junction="-1">{link}<planView>
            <geometry s="0" x="{x}" y="0" hdg="0" length="50"><line/></geometry></planView>
            <lanes><laneSection s="0"><center><lane id="0" type="none"/></center><right>
            <lane id="-1" type="driving"><link><successor id="-1"/></link>
            <width sOffset="0" a="3.5" b="0" c="0" d="0"/></lane>
            </right></laneSection></lanes></road>"#
        )
    };
    let xodr = format!(
        "<OpenDRIVE><header/>{}{}</OpenDRIVE>",
        road(
            "1",
            0.0,
            r#"<link><successor elementType="road" elementId="2"/></link>"#
        ),
        road("2", 50.0, "")
    );
    let (net, prov) = load_str_with_provenance(&xodr).unwrap();
    assert_eq!(
        prov.warnings,
        [Warning::ContactPointMissing {
            road_id: "1".into(),
            end: RoadEnd::End,
        }]
    );
    let into = net.lane(lane(&prov, "1", -1)).unwrap();
    assert_eq!(into.successors, [lane(&prov, "2", -1)]);
}
